\section{Method}\label{sec:method}

We use the following terms:

\begin{description}
\item[Latency] time to first token.
\item[\textbf{Throughput}] tokens per second.
\end{description}

\begin{algorithm}
\caption{Compute squares}
\label{alg:sq}
\begin{algorithmic}[1]
\State \textbf{Input:} array $A$ 
\State \textbf{for} $i = 1$ to $n$ \textbf{do}
  \State $A[i] \gets A[i]^2$ 
\State \textbf{return} $A$ 
\end{algorithmic}
\end{algorithm}

